-- 20260120061000_seed_harvey_policy_examples_expanded.sql
-- Harvey Dataset: 1,282 policy_examples for RAG
-- Generated from harvey_policy_examples_db_ready.jsonl
-- Idempotent: uses ON CONFLICT DO NOTHING

DO $$
DECLARE
  org_id uuid;
  bp_version_id uuid;
  mp_id uuid;
  ct_id uuid;
BEGIN
  -- Get org
  SELECT id INTO org_id
  FROM organizations
  ORDER BY created_at ASC
  LIMIT 1;

  -- Get blueprint version
  SELECT rbv.id INTO bp_version_id
  FROM review_blueprint_versions rbv
  JOIN review_blueprints rb ON rb.id = rbv.blueprint_id
  WHERE rb.organization_id = org_id
    AND rb.name LIKE '%Amazon%'
    AND rbv.version_int = 1
  LIMIT 1;

  IF bp_version_id IS NULL THEN
    RAISE EXCEPTION 'Blueprint version not found. Run taxonomy seeds first.';
  END IF;


  

-- rights_ownership / rights_exclusive_ownership_universe_perpetuity (20 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'rights_ownership'
    AND ct.code = 'rights_exclusive_ownership_universe_perpetuity';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



