    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall own exclusively, in perpetuity, throughout the universe, all right, title and interest in and to the Program and all elements thereof, including without limitation all Materials, in all media whether now known or hereafter devised.', ARRAY['exclusive ownership','perpetuity','universe','all right title interest','Program','Materials','all media']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Standard Amazon position - complete ownership grant", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "This is Amazon''s standard position establishing complete, exclusive, perpetual ownership throughout the universe in all media. No qualifications or limitations that would require escalation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All right, title and interest of every kind and nature in and to the Program, including all Materials created in connection therewith, shall vest exclusively in Amazon in perpetuity and throughout the universe, free and clear of any claims, liens or encumbrances.', ARRAY['vest exclusively','perpetuity','universe','free and clear','no encumbrances','Program','Materials']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Alternative acceptable formulation with anti-encumbrance language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Achieves same result as standard position with additional protective language regarding encumbrances. Fully acceptable without approval."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall be the sole and exclusive owner in perpetuity throughout the universe of all right, title and interest in the Program, all versions and iterations thereof, and all Materials, for exploitation in any and all media and by any and all means.', ARRAY['sole exclusive owner','perpetuity','universe','all versions iterations','all media','all means']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Expanded language covering versions/iterations explicitly", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly addresses versions and iterations which strengthens Amazon''s position. Standard acceptable formulation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The Program and all Materials shall be owned exclusively by Amazon Content Services LLC and its successors and assigns, in perpetuity, throughout the universe, in all media now known or hereafter developed.', ARRAY['owned exclusively','successors assigns','perpetuity','universe','all media','hereafter developed']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Includes successors/assigns language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit inclusion of successors and assigns is consistent with Amazon''s assignment flexibility. Standard acceptable position."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall own in perpetuity and throughout the universe, exclusively and without limitation, all right, title and interest in and to: (a) the Program; (b) all Materials; (c) all ancillary and subsidiary rights therein; and (d) all proceeds and income therefrom.', ARRAY['perpetuity','universe','exclusive','Program','Materials','ancillary subsidiary rights','proceeds income']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Detailed enumeration format with proceeds", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerated format provides additional clarity and explicitly captures proceeds/income. Acceptable variation of standard position."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'From the commencement of production and continuing in perpetuity throughout the universe, Amazon shall exclusively own all right, title and interest in and to the Program and Materials for all purposes and in all media whether now existing or later created.', ARRAY['commencement of production','perpetuity','universe','exclusive','all purposes','all media','later created']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Specifies timing of ownership vesting", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that ownership vests from commencement rather than delivery. This is favorable to Amazon and acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall be entitled to the exclusive ownership throughout the universe in perpetuity of all right, title and interest of whatsoever nature in the Programme and all Materials, including all copyrights, database rights, and intellectual property rights therein.', ARRAY['exclusive ownership','universe','perpetuity','Programme','Materials','copyrights','database rights','intellectual property']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "UK spelling and additional IP enumeration for UK productions", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK variant with appropriate spelling and explicit database rights reference (relevant under UK/EU law). Acceptable for UK productions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own exclusively, in perpetuity, throughout the universe, all right, title and interest in and to the Program and Materials, excluding only ProdCo''s pre-existing intellectual property contributed to the Program which shall be licensed to Amazon on an exclusive, perpetual, royalty-free basis.', ARRAY['exclusive ownership','perpetuity','universe','excluding pre-existing IP','perpetual license','royalty-free']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "ProdCo carveout for pre-existing IP with back-license", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for pre-existing IP is a common ProdCo request. Acceptable if the license grant is truly perpetual, exclusive, and royalty-free, but requires Legal review to verify scope of pre-existing IP."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own all right, title and interest in and to the Program and Materials exclusively, in perpetuity, throughout the universe; provided that Amazon acknowledges ProdCo''s retained trademark rights in ProdCo''s corporate name and logo.', ARRAY['exclusive ownership','perpetuity','universe','retained trademark','corporate name logo']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "ProdCo trademark retention for corporate identity", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Retention of ProdCo''s own corporate name/logo trademarks is generally acceptable as these don''t relate to Program content, but requires Legal confirmation that carveout is appropriately narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own exclusively, in perpetuity, throughout the universe, all right, title and interest in the Program and Materials, provided that upon termination of Amazon''s exploitation of the Program for a continuous period of ten (10) years, all such rights shall revert to ProdCo.', ARRAY['exclusive ownership','perpetuity','universe','reversion','ten years','cessation of exploitation']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Turnaround/reversion provision", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Reversion clauses fundamentally undermine perpetual ownership. Requires senior Legal approval and likely pushback, but may be negotiable for limited scope or extended timeframe."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own exclusively, in perpetuity and throughout the universe, all right, title and interest in the Program, subject to any customary residual or reuse payment obligations to guilds and unions as may be applicable.', ARRAY['exclusive ownership','perpetuity','universe','residual obligations','guild union','reuse payments']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Guild residual carveout", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledgment of guild residuals is standard industry practice and doesn''t affect ownership. Business Affairs should confirm specific guild applicability."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own all right, title and interest in the Program and Materials exclusively, in perpetuity, throughout the universe, except that ProdCo shall retain the exclusive right to produce theatrical sequel and prequel motion pictures.', ARRAY['exclusive ownership','perpetuity','universe','sequel prequel carveout','theatrical motion pictures']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Sequel/prequel theatrical carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Sequel/prequel carveouts significantly limit Amazon''s ability to expand the franchise. Requires Legal approval and is likely to be heavily negotiated or rejected."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own exclusively all right, title and interest in the Programme and Materials in perpetuity throughout the universe. ProdCo shall retain moral rights in the Programme to the extent such rights are not waivable under applicable law, but covenants not to enforce or exercise such rights.', ARRAY['exclusive ownership','perpetuity','universe','moral rights','non-waivable','covenant not to enforce']::text[], '{"doc": "PSA_Fallbacks", "section": "Rights/Ownership", "note": "EU/UK moral rights acknowledgment with non-exercise covenant", "approval": "AMAZON_LEGAL", "jurisdiction": "EU", "risk_level": "MEDIUM", "reasoning": "In jurisdictions where moral rights cannot be waived (France, Germany), a covenant not to exercise is the standard fallback. Requires Legal confirmation of jurisdiction-specific requirements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall own exclusively, in perpetuity, throughout the universe, all right, title and interest in and to the Program and Materials, provided that ProdCo shall retain ownership of all underlying intellectual property, formats, characters, and storylines for use in any medium.', ARRAY['exclusive ownership','perpetuity','universe','retained underlying IP','formats','characters','storylines']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "ProdCo attempts to retain core underlying rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Retention of underlying IP, formats, characters and storylines would eviscerate Amazon''s ownership of the Program. This creates significant sequel/spinoff risk and is fundamentally incompatible with Amazon''s position."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall own all right, title and interest in the Program and Materials, and hereby grants to Amazon an exclusive license throughout the universe for a period of fifteen (15) years from initial delivery.', ARRAY['ProdCo ownership','exclusive license','fifteen years','limited term']::text[], '{"doc": "Counterparty_Proposal", "section": "Rights/Ownership", "note": "Complete inversion - license model instead of ownership", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "This fundamentally inverts the ownership structure. Amazon requires ownership, not a license. A 15-year term is wholly inadequate for content investment. Reject outright."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall own exclusively all right, title and interest in the Program in perpetuity throughout the Territory, defined as North America and the United Kingdom only.', ARRAY['exclusive ownership','perpetuity','limited territory','North America','UK']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Territorial limitation on ownership", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Amazon requires universe-wide ownership. Territorial limitations are incompatible with global streaming distribution model and would create significant exploitation complications."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon and ProdCo shall jointly own all right, title and interest in the Program and Materials, with each party having the right to exploit the Program independently without accounting to the other.', ARRAY['joint ownership','independent exploitation','no accounting']::text[], '{"doc": "Counterparty_Proposal", "section": "Rights/Ownership", "note": "Joint ownership proposal", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Joint ownership creates deadlock risk, complicates chain of title, and allows ProdCo to license to competitors. Amazon must be sole owner. Not acceptable under any circumstances."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall own all right, title and interest in the Program, provided that such ownership shall terminate and revert to ProdCo upon the earlier of (i) Amazon''s material breach of this Agreement, or (ii) Amazon''s failure to produce a second season within twenty-four (24) months.', ARRAY['ownership','termination','reversion','material breach','second season trigger']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Conditional ownership with reversion triggers", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Ownership conditioned on production commitments or breach is fundamentally unacceptable. Amazon cannot have ownership that can be lost through operational decisions. This creates unacceptable risk exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall own the Program exclusively throughout the universe during the License Period, which shall commence on First Exploitation and continue for a period of seven (7) years, renewable at Amazon''s option for successive one (1) year periods.', ARRAY['exclusive','limited license period','seven years','renewal option']::text[], '{"doc": "Counterparty_Proposal", "section": "Rights/Ownership", "note": "Term ownership with renewal structure", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Seven-year term with renewals is a license structure, not ownership in perpetuity. Renewal options create uncertainty. Amazon requires perpetual ownership without conditions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall own all right, title and interest in the Program exclusively, in perpetuity, throughout the universe, subject to ProdCo''s reserved right to produce up to two (2) additional seasons for any third party distributor if Amazon does not exercise its option for such additional seasons within twelve (12) months.', ARRAY['exclusive ownership','perpetuity','universe','reserved right','additional seasons','third party distributor']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Third party production carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "This allows ProdCo to take the show to a competitor if Amazon doesn''t greenlight additional seasons. Fundamentally incompatible with exclusive ownership and creates competitive exposure."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The Program and all Materials shall be considered a ''work made for hire'' for Amazon within the meaning of the U.S. Copyright Act. To the extent any element does not qualify as a work made for hire, ProdCo hereby irrevocably assigns to Amazon all right, title and interest therein.', ARRAY['work made for hire','Copyright Act','irrevocable assignment','backstop','all right title interest']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Standard US WMFH with assignment backstop", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "This is Amazon''s standard formulation combining WMFH status with an assignment backstop to capture any elements that might not qualify as WMFH under the Copyright Act''s enumerated categories."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All Materials and the Program are created as works made for hire for Amazon, and Amazon is deemed the author thereof for all purposes. In the event any Materials or the Program do not qualify as works made for hire under applicable law, ProdCo assigns and agrees to assign to Amazon in perpetuity all right, title and interest therein, including all copyrights.', ARRAY['works made for hire','Amazon as author','assignment','perpetuity','copyrights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Includes authorship acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly designates Amazon as author for copyright purposes and includes present and future assignment language. Standard acceptable position."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges and agrees that: (a) all Materials and the Program are specially ordered or commissioned works made for hire for Amazon; (b) Amazon is and shall be considered the author and owner thereof; and (c) to the extent any element is determined not to be a work made for hire, ProdCo hereby assigns, transfers and conveys all right, title and interest in such element to Amazon.', ARRAY['specially ordered commissioned','works made for hire','author owner','assigns transfers conveys']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Detailed acknowledgment format", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive language addressing multiple WMFH requirements under the Copyright Act. The acknowledgment of ''specially ordered or commissioned'' supports WMFH status for certain categories."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The Program and Materials are works made for hire owned by Amazon. Without limiting the foregoing, ProdCo irrevocably assigns to Amazon all right, title and interest in the Program and Materials throughout the universe in perpetuity, including all renewals and extensions of copyright.', ARRAY['works made for hire','irrevocable assignment','universe','perpetuity','renewals extensions copyright']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Includes renewal/extension language for pre-1978 works considerations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes copyright renewal and extension language which provides additional protection. Standard acceptable formulation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The Programme and all Materials constitute works created by ProdCo at Amazon''s request pursuant to a commission for the purposes of section 9(2)(aa) of the Copyright, Designs and Patents Act 1988. ProdCo hereby assigns to Amazon by way of present assignment of future copyright all right, title and interest in the Programme and Materials in perpetuity throughout the universe.', ARRAY['commission','CDPA 1988','present assignment future copyright','perpetuity','universe']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "UK commissioned works formulation", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate language referencing CDPA 1988 commissioned works provisions. Present assignment of future copyright ensures chain of title vests upon creation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All Materials and the Program are works made for hire. ProdCo irrevocably assigns to Amazon now and in the future all right, title and interest in the Program and Materials, including all copyrights, neighboring rights, and all other intellectual property rights, in all languages, for all purposes, throughout the universe, in perpetuity.', ARRAY['works made for hire','irrevocable assignment','copyrights','neighboring rights','all languages','universe','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Expanded IP coverage including neighboring rights", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes neighboring rights (relevant for performers, broadcasters in civil law jurisdictions) and multi-language coverage. Comprehensive and acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'To the fullest extent permitted by applicable law, the Program and Materials shall be deemed works made for hire. To the extent that any jurisdiction does not recognize the work made for hire doctrine, or to the extent any Materials or elements thereof are not works made for hire, ProdCo hereby absolutely and irrevocably assigns to Amazon all right, title and interest therein in perpetuity throughout the universe.', ARRAY['fullest extent','works made for hire','jurisdiction','irrevocable assignment','perpetuity','universe']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Multi-jurisdiction protective language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledges jurisdictional variations in WMFH doctrine and ensures assignment backstop covers all scenarios. Appropriate for international productions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The Program and Materials shall be works made for hire for Amazon. To the extent any element does not qualify as a work made for hire, ProdCo assigns all right, title and interest therein to Amazon, subject to ProdCo''s receipt of the applicable portion of the Production Fee for such element.', ARRAY['works made for hire','assignment','subject to payment','production fee']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Assignment conditioned on payment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Conditioning assignment on payment introduces chain of title risk. Legal should confirm whether this is acceptable given payment structure and timing."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The Program and Materials are works made for hire for Amazon. ProdCo assigns to Amazon all right, title and interest therein, provided that ProdCo shall have a perpetual, non-exclusive, royalty-free license to use clips from the Program (not exceeding thirty seconds) for portfolio and self-promotional purposes only.', ARRAY['works made for hire','assignment','back-license','clips','portfolio','self-promotion']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Promotional clip license for ProdCo", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited promotional clip license is commonly requested by production companies for portfolio purposes. Requires Legal approval to ensure appropriate restrictions (timing, context, no competitive use)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All Materials and the Program shall be works made for hire for Amazon. ProdCo assigns all right, title and interest therein to Amazon, except that any music composed specifically for the Program shall be subject to a separate music agreement between Amazon and the applicable composer.', ARRAY['works made for hire','assignment','music carveout','separate agreement','composer']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Music rights carved out to separate agreement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Music rights often require separate treatment due to publishing, sync, and performance royalty considerations. Acceptable if separate agreement exists and is on Amazon-favorable terms."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo acknowledges that the Programme and Materials constitute commissioned works under applicable EU law. ProdCo hereby assigns and transfers to Amazon all economic rights in the Programme and Materials throughout the universe in perpetuity, to the extent permitted by applicable law.', ARRAY['commissioned works','EU law','economic rights','universe','perpetuity','extent permitted']::text[], '{"doc": "PSA_Fallbacks", "section": "Work-Made-For-Hire", "note": "EU-compliant economic rights transfer", "approval": "AMAZON_LEGAL", "jurisdiction": "EU", "risk_level": "MEDIUM", "reasoning": "EU jurisdictions distinguish between economic and moral rights. ''To the extent permitted'' qualifier may require Legal review to confirm comprehensive coverage in applicable EU member state."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The Program and Materials are works made for hire. ProdCo assigns all right, title and interest therein to Amazon, provided that any pre-existing materials owned by ProdCo prior to commencement of services and incorporated into the Program shall be licensed to Amazon on exclusive, perpetual, royalty-free terms as set forth in Schedule B.', ARRAY['works made for hire','assignment','pre-existing materials','exclusive license','Schedule B']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Pre-existing materials license structure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Schedule B must be reviewed to ensure license terms are truly perpetual, exclusive, and include all necessary rights. Chain of title for pre-existing materials requires diligence."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The Program and Materials shall be considered works made for hire for Amazon. To the extent any element does not so qualify, ProdCo hereby assigns all right, title and interest therein to Amazon. This assignment is effective upon execution of this Agreement and is not subject to any termination rights under 17 U.S.C. § 203.', ARRAY['works made for hire','assignment','Section 203','termination rights','waiver']::text[], '{"doc": "PSA_Fallbacks", "section": "Work-Made-For-Hire", "note": "Section 203 termination waiver language", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Section 203 termination rights can''t be waived prospectively under US law, but acknowledgment of WMFH status helps avoid 203 applying. Legal should confirm language effectiveness."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall own all right, title and interest in the Program and Materials as works made for hire, and hereby grants Amazon an exclusive license to exploit the Program during the Term.', ARRAY['ProdCo ownership','works made for hire','exclusive license','Term']::text[], '{"doc": "Counterparty_Proposal", "section": "Work-Made-For-Hire", "note": "Inverted WMFH - ProdCo as commissioning party", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Fundamentally inverts the WMFH relationship. Amazon must be the commissioning party and owner. This is legally and commercially unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The Program shall be a work made for hire for Amazon. However, any Materials created by ProdCo employees or independent contractors shall remain the property of ProdCo, and ProdCo grants Amazon a non-exclusive license to use such Materials solely in connection with the Program.', ARRAY['works made for hire','Materials excluded','ProdCo property','non-exclusive license']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Carveout for ProdCo-created materials", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding Materials from the WMFH/assignment structure creates significant chain of title problems. Non-exclusive license is wholly inadequate. Amazon must own all Materials."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The Program and Materials are works made for hire. To the extent any element does not qualify as a work made for hire, ProdCo shall assign such rights to Amazon upon Amazon''s written request and payment of additional consideration to be negotiated in good faith.', ARRAY['works made for hire','conditional assignment','written request','additional consideration']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Assignment conditioned on request and additional payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Assignment backstop must be automatic and unconditional. Requiring additional consideration or written request creates gap in chain of title and exposes Amazon to ransom risk."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo acknowledges the Program is a work made for hire. ProdCo assigns to Amazon all right, title and interest therein for the Initial Term of five (5) years, after which all rights shall revert to ProdCo.', ARRAY['work made for hire','assignment','limited term','five years','reversion']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Term-limited assignment with reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Assignment must be perpetual. Term-limited assignment with reversion contradicts WMFH status and creates unacceptable rights uncertainty. Reject."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The Program shall be a work made for hire for Amazon. ProdCo assigns all right, title and interest therein, subject to ProdCo''s retained right to terminate this assignment if Amazon fails to release the Program within eighteen (18) months of Delivery.', ARRAY['work made for hire','assignment','termination right','release deadline','eighteen months']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Assignment subject to release obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Assignment subject to termination for failure to release creates unacceptable operational constraint and rights uncertainty. Amazon must have unfettered ownership regardless of release decisions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo agrees the Program is a work made for hire. In the alternative, ProdCo assigns all right, title and interest therein to Amazon, provided that Amazon shall not have the right to create derivative works, sequels, prequels, or spinoffs without ProdCo''s prior written consent.', ARRAY['work made for hire','assignment','derivative works restriction','consent required']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Derivative works consent requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Restricting derivative work rights contradicts full ownership. Amazon must have unfettered ability to create sequels, prequels, spinoffs. This limitation is commercially unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'To the extent the Program qualifies as a work made for hire, Amazon shall be deemed the author. To the extent it does not so qualify, the parties shall negotiate in good faith regarding the allocation of rights therein.', ARRAY['work made for hire','if qualifies','good faith negotiation','rights allocation']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "No automatic assignment backstop", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Future negotiation is not an acceptable backstop to WMFH. Creates gap in chain of title and potential deadlock. Assignment backstop must be automatic and comprehensive."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s ownership and exploitation rights shall extend to all media, formats, platforms and technologies now known or hereafter devised, invented or developed, throughout the universe, in perpetuity.', ARRAY['all media','formats','platforms','technologies','now known','hereafter devised','universe','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Standard future media language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive future media language ensuring Amazon can exploit the Program on platforms and in formats that don''t exist yet. Standard industry language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The rights granted herein include the right to exhibit, distribute, market and otherwise exploit the Program by any and all means and media, whether now known or hereafter devised, including without limitation theatrical, home video, television, streaming, mobile, interactive, and any technology developed in the future.', ARRAY['all means media','now known hereafter devised','theatrical','home video','television','streaming','mobile','interactive','future technology']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Enumerated media with future catch-all", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Combines specific enumeration of current media with catch-all future language. Provides additional clarity while maintaining comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have the exclusive right to exploit the Program in all media and formats of every kind and nature, whether now existing or hereafter created, including all linear and non-linear platforms, over-the-top services, SVOD, AVOD, TVOD, EST, and any successor or analogous technologies.', ARRAY['all media formats','linear non-linear','OTT','SVOD','AVOD','TVOD','EST','successor technologies']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Streaming-specific enumeration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates current streaming business models (SVOD, AVOD, etc.) while capturing future analogous technologies. Appropriate for streaming-first content."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s rights extend to exhibition, distribution and exploitation in any and all media and by any and all means, methods and devices now or hereafter known, discovered, devised, developed or invented anywhere in the universe.', ARRAY['all media','all means methods devices','now or hereafter','known discovered devised developed invented','universe']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Expansive verb coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Multiple synonymous verbs (known, discovered, devised, developed, invented) provide maximum coverage against potential future challenges based on unforeseen technologies."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Without limiting Amazon''s ownership, Amazon shall have the sole and exclusive right to exploit the Program throughout the universe in perpetuity in and by means of all media, whether now in existence or later invented, including without limitation cinema, broadcast, cable, satellite, internet, wireless, virtual reality, augmented reality, and all future technologies.', ARRAY['all media','now existing','later invented','cinema','broadcast','cable','satellite','internet','wireless','VR','AR','future technologies']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Includes emerging tech (VR/AR)", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly includes VR and AR which are increasingly relevant for content exploitation. Comprehensive enumeration with future catch-all."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may exploit the Programme by all means and in all media and formats of audiovisual and sound recording exploitation, whether now known or hereafter devised, including all forms of digital distribution, electronic sell-through and any analogous future technology throughout the world in perpetuity.', ARRAY['all means media formats','audiovisual','sound recording','digital distribution','electronic sell-through','future technology','world','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "UK production language", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate language with comprehensive media coverage. ''World'' can be used interchangeably with ''universe'' in UK agreements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The rights herein shall include the right to exploit the Program in all audiovisual and audio-only media, all interactive and non-interactive formats, and by all means and methods of delivery and distribution, whether analog or digital, now existing or later developed.', ARRAY['audiovisual','audio-only','interactive','non-interactive','analog','digital','now existing','later developed']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Format-agnostic language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Captures both audiovisual and audio-only exploitation, and interactive/non-interactive distinction. Comprehensive and future-proof."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program in all media now known or hereafter devised, provided that exploitation in any media not currently contemplated by the parties shall be subject to good faith consultation with ProdCo.', ARRAY['all media','now known hereafter devised','good faith consultation','future media']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Consultation requirement for future media", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation (as opposed to consent) may be acceptable if it doesn''t create a blocking right. Legal should confirm ''consultation'' doesn''t operate as consent requirement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s exploitation rights extend to all media now known or hereafter devised, except that exploitation via direct neural interface or similar brain-computer interface technology shall require mutual agreement of the parties.', ARRAY['all media','now known hereafter devised','neural interface','BCI','mutual agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Carveout for speculative future tech", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for extremely speculative technology (neural interfaces) may be negotiable as a ProdCo compromise. Legal should assess whether carveout is appropriately narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program in all media now known or hereafter devised throughout the universe, provided that Amazon shall pay to ProdCo additional compensation as separately agreed for exploitation in any media not existing as of the date hereof and generating material revenue.', ARRAY['all media','now known hereafter devised','additional compensation','future media','material revenue']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Future media compensation requirement", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Additional compensation for future media is a ProdCo ask. Business Affairs should determine whether this is acceptable and, if so, define ''material revenue'' threshold."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s rights include exploitation in all media now known or hereafter devised, including virtual reality and augmented reality. For the avoidance of doubt, Amazon may create immersive, interactive and gaming experiences based on the Program without additional compensation.', ARRAY['all media','VR','AR','immersive','interactive','gaming','no additional compensation']::text[], '{"doc": "PSA_Fallbacks", "section": "Rights/Ownership", "note": "Explicit VR/AR/gaming clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly addresses emerging exploitation modes that are sometimes disputed. May preempt future VR/gaming compensation claims. Legal should confirm language adequacy."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have the exclusive right to exploit the Program in all media now known or hereafter devised; provided that any theatrical release shall be subject to Amazon''s separate theatrical distribution agreement then in effect.', ARRAY['all media','now known hereafter devised','theatrical release','separate agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Theatrical subject to separate terms", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Reference to separate theatrical agreement may be appropriate for productions with theatrical component. Business Affairs should confirm standard theatrical terms are acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The rights granted herein extend to all media now known or hereafter devised, provided that Amazon''s exploitation rights in respect of the soundtrack album shall be limited to promotional use only, with commercial soundtrack rights reserved to ProdCo''s affiliated music company.', ARRAY['all media','soundtrack','promotional use only','music company','commercial rights reserved']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Soundtrack carveout for music affiliate", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Soundtrack carveout is significant but may be negotiable depending on music component value. Requires Legal assessment of impact on ancillary exploitation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program via streaming platforms only. All other media rights, including theatrical, broadcast, home video and physical media, are expressly reserved to ProdCo.', ARRAY['streaming only','reserved rights','theatrical','broadcast','home video','physical media']::text[], '{"doc": "Counterparty_Proposal", "section": "Rights/Ownership", "note": "Streaming-only license with reserved rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting Amazon to streaming-only rights is fundamentally incompatible with ownership model. Amazon must have all media rights to fully exploit and monetize the Program."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s exploitation rights shall be limited to media existing as of the Effective Date of this Agreement. Rights to exploit the Program in any media developed after the Effective Date shall require separate negotiation and additional compensation.', ARRAY['limited to existing media','future media excluded','separate negotiation','additional compensation']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Future media exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding future media entirely defeats the purpose of perpetual ownership. Technology evolution is certain; Amazon cannot be held hostage to future negotiations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program in all media now known or hereafter devised, subject to ProdCo''s prior written consent for any exploitation not specifically enumerated in Exhibit C.', ARRAY['all media','ProdCo consent','enumerated rights','Exhibit C']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Consent requirement for non-enumerated media", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Prior consent requirement for non-enumerated media creates blocking right that undermines ownership. ProdCo cannot have approval rights over Amazon''s exploitation decisions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s media rights shall include streaming, download-to-own, and linear broadcast. Amazon shall not have the right to exploit the Program in theatrical exhibition, gaming, merchandise, theme parks or location-based entertainment without ProdCo''s separate consent and payment of additional fees.', ARRAY['limited media','no theatrical','no gaming','no merchandise','no theme parks','consent required','additional fees']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Significant ancillary rights carveouts", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Carving out theatrical, gaming, merchandise and theme parks represents massive value leakage. These ancillary rights are essential components of full ownership."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program in the English language in all media now known or hereafter devised. Rights to exploit dubbed or subtitled versions in other languages shall be subject to separate agreement.', ARRAY['English language only','dubbed subtitled','other languages','separate agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Language restriction on media rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Language restrictions fundamentally undermine global exploitation. Amazon requires rights in all languages as part of its worldwide streaming model."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program in all media now known. The parties shall meet annually to discuss in good faith the allocation of rights to any new media technologies developed during the preceding year.', ARRAY['now known only','annual meeting','good faith discussion','new media allocation']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Future media subject to annual negotiation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Annual negotiation structure creates perpetual uncertainty and potential deadlock. Amazon must have automatic rights to all future media without ongoing consent requirements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s exploitation rights extend to all media now known or hereafter devised; provided that Amazon shall share equally with ProdCo all revenue generated from exploitation in any media category not specifically identified in Exhibit D.', ARRAY['all media','revenue sharing','fifty percent','unidentified media','Exhibit D']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "50/50 revenue share on future media", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Revenue sharing on future media is inconsistent with fee-based PSA structure where Amazon pays production fee for full ownership. This introduces profit participation through back door."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall execute and deliver such further documents and instruments, and take such further actions, as Amazon may reasonably request to evidence, perfect or protect Amazon''s ownership of the Program and Materials, including execution of copyright assignments and any documents required for registration with applicable copyright offices.', ARRAY['further documents','instruments','reasonably request','evidence','perfect','protect','ownership','copyright assignments','registration']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Standard further assurances language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard further assurances provision ensuring ProdCo will provide any documentation needed to perfect Amazon''s ownership. Essential for chain of title."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon Amazon''s request, ProdCo shall promptly execute, acknowledge and deliver to Amazon any and all documents, instruments and assignments that Amazon deems necessary or desirable to confirm, establish or protect Amazon''s exclusive ownership of the Program and all Materials in any jurisdiction.', ARRAY['promptly execute','acknowledge','deliver','documents instruments assignments','necessary desirable','exclusive ownership','any jurisdiction']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Expanded further assurances with jurisdictional coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Multi-jurisdictional coverage is important for international productions and registrations. Standard acceptable language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo agrees to sign, execute and deliver any documents, certificates, assignments or instruments of conveyance as may be required by Amazon to transfer, assign, register or otherwise evidence Amazon''s ownership of the Program and Materials, including short-form copyright assignments suitable for recording with the U.S. Copyright Office.', ARRAY['sign execute deliver','documents certificates assignments','transfer assign register','short-form copyright assignments','Copyright Office']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Specific Copyright Office reference", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly references short-form assignments for Copyright Office recording, which is standard practice for evidencing chain of title. Acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall cooperate fully with Amazon in connection with the registration or recordation of the Program or any component thereof with any governmental agency, guild, performing rights organization, or collective management organization, and shall execute all documents reasonably required therefor.', ARRAY['cooperate fully','registration recordation','governmental agency','guild','PRO','collective management organization','execute documents']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Expanded registration scope including guilds/PROs", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes guild and PRO registrations which are necessary for proper rights administration. Comprehensive and acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'At any time and from time to time, upon Amazon''s request, ProdCo shall do, execute, acknowledge and deliver, or cause to be done, executed, acknowledged and delivered, all such further acts, deeds, assignments, conveyances, powers of attorney and assurances as may be required to carry out the intent of this Agreement and to vest in Amazon all right, title and interest in the Program and Materials.', ARRAY['at any time','further acts deeds','assignments conveyances','powers of attorney','assurances','vest','right title interest']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Comprehensive further assurances with POA reference", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive language covering full range of potential documentation needs. Reference to powers of attorney anticipates potential execution issues."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo undertakes to execute and deliver to Amazon all deeds of assignment and other documents as Amazon may reasonably require to perfect or evidence Amazon''s title to the Programme and Materials in any part of the world, and to enable Amazon to register such title with all relevant collecting societies and copyright registries.', ARRAY['deeds of assignment','reasonably require','perfect evidence title','any part of world','collecting societies','copyright registries']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "UK formulation with collecting societies", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate language addressing collecting society registrations (PRS, PPL, etc.) which are important for proper UK rights administration."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall procure that each contributor to the Program executes such documents as Amazon may require to confirm the assignment of rights to Amazon, and ProdCo shall deliver to Amazon copies of all executed contributor agreements upon request.', ARRAY['procure','contributor','executed documents','confirm assignment','contributor agreements','deliver copies']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Contributor agreement procurement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends further assurances to underlying contributors, ensuring complete chain of title documentation. Essential for proper rights clearance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall execute and deliver such further documents as Amazon may reasonably request to evidence Amazon''s ownership, provided that (i) Amazon shall bear all costs of registration and recording fees, and (ii) Amazon shall provide ProdCo with copies of all filed documents.', ARRAY['further documents','reasonably request','Amazon bears costs','registration fees','copies to ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Cost allocation and copy requirements", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Cost allocation for registrations is reasonable and often assumed. Copy provision is administrative. Business Affairs should confirm acceptability."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall execute such further instruments as Amazon may reasonably request, provided that Amazon''s requests shall not require ProdCo to make any representation or warranty beyond those set forth in this Agreement or to incur any unreimbursed expense.', ARRAY['further instruments','reasonably request','no additional reps warranties','no unreimbursed expense']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Limitations on further assurances scope", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limitations on additional reps/warranties may be acceptable if Agreement reps are comprehensive. Legal should confirm existing reps are adequate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon reasonable advance notice, ProdCo shall execute documents to evidence Amazon''s ownership and to enable registration with copyright offices. ProdCo shall have five (5) business days to review and execute such documents; Amazon shall consider in good faith any reasonable comments from ProdCo.', ARRAY['reasonable advance notice','five business days','review period','good faith','reasonable comments']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Review period for further assurances", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Five-day review period is short and may be acceptable. ''Good faith consideration'' of comments is not a consent right. Legal should confirm this doesn''t create blocking opportunity."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall execute further documents reasonably requested by Amazon. In the event ProdCo fails to do so within fifteen (15) business days of Amazon''s written request, ProdCo hereby appoints Amazon as its attorney-in-fact to execute such documents on ProdCo''s behalf.', ARRAY['further documents','fifteen business days','attorney-in-fact','execute on behalf']::text[], '{"doc": "PSA_Fallbacks", "section": "Rights/Ownership", "note": "POA with fifteen-day cure period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Fifteen-day period before POA activates is longer than ideal (standard is immediate or shorter). Legal should confirm acceptable timing."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall provide reasonable cooperation and execute documents as Amazon may request for registration purposes, subject to the availability of appropriate personnel. ProdCo shall use commercially reasonable efforts to ensure such personnel are available.', ARRAY['reasonable cooperation','registration','subject to availability','commercially reasonable efforts']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Availability qualification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Availability qualification could create delays, but ''commercially reasonable efforts'' standard provides some comfort. Legal should assess whether this is acceptable given POA backup."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall execute such documents as Amazon may reasonably request for registration purposes, provided that Amazon shall not register the Program with any government agency or copyright office that ProdCo reasonably believes would require ProdCo to disclose confidential business information unrelated to the Program.', ARRAY['reasonably request','registration','confidential business information','unrelated to Program']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Confidential information carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Narrow carveout for truly confidential unrelated information may be reasonable. Legal should assess scope and ensure it doesn''t impede necessary registrations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall execute such further documents as Amazon may reasonably request, provided that ProdCo shall have the right to approve the form and content of any such documents, which approval shall not be unreasonably withheld.', ARRAY['further documents','ProdCo approval right','form and content','not unreasonably withheld']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Approval right over documentation form", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Approval right over document form creates potential blocking mechanism. Standard registration forms should not require ProdCo consent. This impedes chain of title perfection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall execute further documents upon Amazon''s request, provided that ProdCo shall not be obligated to execute any document that ProdCo believes, in its sole discretion, contains terms inconsistent with this Agreement or is otherwise objectionable to ProdCo.', ARRAY['further documents','ProdCo sole discretion','inconsistent terms','objectionable']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "ProdCo sole discretion to refuse", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo''s ''sole discretion'' to determine consistency or objectionability creates absolute blocking right. This fundamentally undermines the further assurances obligation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Upon receipt of additional compensation to be agreed by the parties, ProdCo shall execute such further documents as Amazon may request to evidence Amazon''s ownership rights.', ARRAY['additional compensation','to be agreed','further documents']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Further assurances conditioned on additional payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Conditioning further assurances on additional payment creates ransom situation. Chain of title perfection is included in the Production Fee and cannot require further consideration."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall execute further documents reasonably requested by Amazon, limited to documents required by the U.S. Copyright Office only. ProdCo shall have no obligation to execute documents for registration in any foreign jurisdiction.', ARRAY['US Copyright Office only','no foreign jurisdiction','limited obligation']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "US-only further assurances", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting further assurances to US only fails to support Amazon''s worldwide exploitation. Foreign registrations are essential for international rights protection and enforcement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall execute further documents requested by Amazon, provided that such requests shall be made only once per calendar year, and ProdCo shall have sixty (60) days to comply with each such request.', ARRAY['once per year','sixty days','limited requests']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Frequency and timing limitations", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Annual request limitation and 60-day response period are wholly inadequate for business needs. Amazon must be able to obtain documentation as needed for transactions and registrations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This Agreement constitutes the entire agreement between the parties regarding assignment of rights. ProdCo shall have no obligation to execute any further documents, assignments, or instruments, and Amazon expressly waives any right to require further assurances.', ARRAY['entire agreement','no further documents','waiver of further assurances']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Elimination of further assurances obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating the further assurances obligation entirely leaves Amazon without ability to perfect chain of title or respond to future registration requirements. This is fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall, subject to ProdCo''s legal counsel''s approval in each instance, execute such documents as Amazon may request. ProdCo''s counsel shall have sole authority to determine whether any requested document is appropriate.', ARRAY['ProdCo counsel approval','each instance','sole authority']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "ProdCo counsel gatekeeping", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring ProdCo counsel approval for each document creates blocking mechanism and potential for endless delay. Amazon cannot be subject to opposing counsel gatekeeping for routine registrations."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo hereby irrevocably appoints Amazon as its attorney-in-fact, coupled with an interest, with full power of substitution, to execute, acknowledge, deliver, file and record any and all documents that Amazon deems necessary or desirable to evidence, establish, protect or enforce Amazon''s rights in the Program and Materials, if ProdCo fails to do so within five (5) business days of Amazon''s request.', ARRAY['irrevocably appoints','attorney-in-fact','coupled with interest','power of substitution','five business days']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Standard POA with short cure period", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard irrevocable POA coupled with an interest, which survives any attempt by ProdCo to revoke. Five-day cure period is appropriate and protects Amazon''s ability to perfect chain of title."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If ProdCo fails or refuses to execute any document required hereunder, Amazon is hereby granted an irrevocable power of attorney, coupled with an interest, to sign such documents in ProdCo''s name and on ProdCo''s behalf. This power of attorney shall survive any termination of this Agreement.', ARRAY['irrevocable power of attorney','coupled with interest','sign in ProdCo''s name','survives termination']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "POA with survival language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit survival provision ensures POA remains effective after Agreement termination. Essential for post-termination chain of title needs."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo hereby constitutes and appoints Amazon and its designees as ProdCo''s true and lawful attorney-in-fact, irrevocably and coupled with an interest, to execute in ProdCo''s name and behalf any documents necessary to effectuate the purposes of this Agreement, including short-form copyright assignments, certificates of engagement, chain of title documents, and registration applications.', ARRAY['true and lawful attorney-in-fact','irrevocable','coupled with interest','designees','copyright assignments','certificates of engagement','chain of title','registration applications']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Detailed POA with specific document types", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific document types covered by POA, providing additional clarity. Inclusion of designees allows Amazon to delegate execution authority."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon is hereby appointed as ProdCo''s irrevocable attorney-in-fact with full authority to execute on ProdCo''s behalf any instruments in writing in the name of ProdCo and to take any actions necessary to vest in Amazon, or any third party authorized by Amazon, all rights contemplated herein, in the event that ProdCo is unable, unwilling or unavailable to do so.', ARRAY['irrevocable attorney-in-fact','unable unwilling unavailable','third party authorized','vest rights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "POA covering inability/unwillingness/unavailability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers multiple scenarios (unable, unwilling, unavailable) ensuring POA is effective regardless of reason for ProdCo''s non-execution. Allows assignment-related executions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The power of attorney granted herein is coupled with an interest and shall be irrevocable. This power shall not be affected by the subsequent disability, incapacity, dissolution, bankruptcy or insolvency of ProdCo. Amazon may exercise this power at any time without notice to ProdCo.', ARRAY['coupled with interest','irrevocable','disability','incapacity','dissolution','bankruptcy','insolvency','no notice']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "POA surviving corporate events", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly addresses corporate events (dissolution, bankruptcy) that might otherwise impair POA effectiveness. No notice requirement provides maximum flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo irrevocably appoints Amazon as its attorney-in-fact to do all acts and execute all documents that may be necessary or desirable to give full effect to the assignment of rights herein, including to register or record such assignment with any governmental authority, copyright office, trademark office, or collecting society anywhere in the world.', ARRAY['irrevocably appoints','attorney-in-fact','register record','governmental authority','copyright office','trademark office','collecting society','anywhere in world']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Global registration authority", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Worldwide scope for registrations ensures Amazon can perfect chain of title in any jurisdiction. Includes collecting societies which are essential for certain territories."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo grants Amazon an irrevocable power of attorney, coupled with an interest, to execute any document in ProdCo''s name as may be required to confirm, secure, evidence, maintain, enforce or protect Amazon''s ownership of the Programme and Materials, including execution of deeds of assignment, waiver of moral rights, and applications for registration.', ARRAY['irrevocable power of attorney','coupled with interest','confirm secure evidence','maintain enforce protect','deeds of assignment','waiver moral rights','registration']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "UK-style POA with moral rights coverage", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate formulation including deeds of assignment and moral rights waivers. Comprehensive authority for UK chain of title needs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo grants Amazon an irrevocable power of attorney to execute documents in ProdCo''s name, which Amazon may exercise only after providing ten (10) business days'' written notice to ProdCo and ProdCo''s failure to respond or execute during such period.', ARRAY['irrevocable power of attorney','ten business days','written notice','failure to respond']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "POA with extended notice period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Ten-day notice period is longer than standard five days but still workable. Legal should confirm this doesn''t unduly delay time-sensitive registrations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo grants Amazon a power of attorney to execute documents on ProdCo''s behalf if ProdCo fails to do so within five (5) business days. Amazon shall provide ProdCo with copies of any documents so executed within ten (10) days of execution.', ARRAY['power of attorney','five business days','copies','ten days']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "POA with copy requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Copy requirement is administrative and does not limit Amazon''s rights. Legal should confirm this is acceptable tracking obligation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon is appointed as ProdCo''s irrevocable attorney-in-fact. Amazon shall exercise this power only through its duly authorized officers or legal counsel, and not through any third party designee without ProdCo''s prior consent.', ARRAY['irrevocable attorney-in-fact','duly authorized officers','legal counsel','no third party','prior consent']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Limitation on POA delegation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting exercise to officers and counsel may be workable but restricts flexibility. Legal should confirm operational acceptability."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo grants Amazon power of attorney to execute chain of title documents. In jurisdictions where powers of attorney must be notarized or authenticated for validity, Amazon shall comply with such formalities, and ProdCo shall reasonably cooperate in any required notarization or authentication.', ARRAY['power of attorney','chain of title','notarization','authentication','ProdCo cooperation']::text[], '{"doc": "PSA_Fallbacks", "section": "Rights/Ownership", "note": "Jurisdiction-specific POA formalities", "approval": "AMAZON_LEGAL", "jurisdiction": "EU", "risk_level": "LOW", "reasoning": "Acknowledges civil law notarization requirements while maintaining ProdCo cooperation obligation. Legal should confirm formality requirements for applicable jurisdictions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo hereby grants Amazon an irrevocable power of attorney, coupled with an interest, to execute documents in ProdCo''s name. This power shall be exercised reasonably and in good faith, and Amazon shall not use this power to modify or expand ProdCo''s substantive obligations under this Agreement.', ARRAY['irrevocable power of attorney','coupled with interest','reasonably','good faith','no expansion of obligations']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "POA with good faith qualifier", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Good faith limitation on POA exercise is reasonable and doesn''t substantively limit Amazon''s chain of title needs. Legal should confirm this doesn''t create dispute opportunity."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon is hereby granted power of attorney to execute documents on ProdCo''s behalf. To the extent permitted by applicable law, this power is coupled with an interest and irrevocable; however, in jurisdictions where such coupling is not recognized, ProdCo covenants not to revoke this power during the Term or thereafter.', ARRAY['power of attorney','coupled with interest','irrevocable','to extent permitted','covenant not to revoke']::text[], '{"doc": "PSA_Fallbacks", "section": "Rights/Ownership", "note": "Jurisdictional fallback for POA", "approval": "AMAZON_LEGAL", "jurisdiction": "EU", "risk_level": "MEDIUM", "reasoning": "Addresses jurisdictions where ''coupled with an interest'' concept may not apply. Covenant not to revoke provides contractual protection. Legal should confirm enforceability in applicable jurisdictions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If ProdCo fails to execute documents within thirty (30) days, Amazon may exercise its power of attorney upon providing ProdCo an additional fifteen (15) days'' cure notice, which ProdCo may extend for an additional fifteen (15) days for good cause.', ARRAY['thirty days','fifteen days cure','extension','good cause']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Extended cure periods with extensions", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Total potential delay of 60+ days before POA can be exercised is commercially unworkable. Amazon needs ability to act promptly on chain of title matters."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s power of attorney shall be revocable by ProdCo upon written notice, provided that revocation shall not be effective if Amazon has already initiated the relevant registration process.', ARRAY['revocable','written notice','exception for initiated process']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Revocable POA", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Revocable POA defeats entire purpose of the provision. Amazon must have irrevocable authority that cannot be withdrawn at ProdCo''s discretion."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo grants Amazon power of attorney to execute documents, limited to applications for copyright registration in the United States only. ProdCo expressly withholds authority to execute any other documents or to make any filings in jurisdictions outside the United States.', ARRAY['limited POA','copyright registration only','US only','no foreign filings']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Geographically and substantively limited POA", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "POA limited to US copyright registration is wholly inadequate for global exploitation model. Amazon needs worldwide authority for all relevant documents."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall not have power of attorney or any authority to execute documents on ProdCo''s behalf. ProdCo shall execute all required documents within a reasonable time following Amazon''s written request.', ARRAY['no power of attorney','no authority','reasonable time']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Complete elimination of POA", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating POA entirely leaves Amazon dependent on ProdCo''s good faith execution. ''Reasonable time'' is undefined and unenforceable. This is fundamentally unacceptable for chain of title."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo grants Amazon power of attorney to execute documents, subject to ProdCo''s right to review and object to any document within fifteen (15) days. If ProdCo objects, the matter shall be submitted to binding arbitration before Amazon may exercise the power of attorney.', ARRAY['power of attorney','ProdCo review','right to object','fifteen days','binding arbitration']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "POA subject to objection and arbitration", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Right to object with arbitration requirement defeats purpose of POA entirely. Amazon would need to arbitrate every document execution, causing massive delays and expense."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s power of attorney shall automatically terminate upon the earlier of (i) three (3) years from the date hereof, or (ii) termination of this Agreement for any reason. Following such termination, Amazon shall have no authority to execute documents on ProdCo''s behalf.', ARRAY['automatic termination','three years','termination of agreement','no authority']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Time-limited POA", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Time-limited or Agreement-termination-limited POA fails to support perpetual ownership. Amazon needs ongoing authority for chain of title maintenance in perpetuity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may, in its sole discretion, grant Amazon a limited power of attorney for specific documents on a case-by-case basis. Any such grant shall be documented in a separate written instrument signed by both parties.', ARRAY['sole discretion','limited POA','case-by-case','separate instrument']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Discretionary case-by-case POA", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Case-by-case POA subject to ProdCo discretion is essentially no POA at all. Amazon requires standing irrevocable authority, not repeated negotiations."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'To the fullest extent permitted by applicable law, ProdCo hereby irrevocably waives and agrees not to assert any and all moral rights, droit moral, or similar rights of authors (including rights of attribution, integrity, disclosure and withdrawal) in and to the Program and Materials in favor of Amazon and its licensees, assignees and successors.', ARRAY['irrevocably waives','not assert','moral rights','droit moral','attribution','integrity','disclosure','withdrawal','licensees assignees successors']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Standard comprehensive moral rights waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive waiver covering all moral rights categories with extension to licensees and successors. Standard Amazon position for US agreements where moral rights are limited."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo waives any moral rights in the Program and Materials to the maximum extent permitted by law, and to the extent such rights cannot be waived, ProdCo agrees not to enforce or exercise such rights against Amazon or any party authorized by Amazon to exploit the Program.', ARRAY['waives moral rights','maximum extent','cannot be waived','not enforce','not exercise','authorized party']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Waiver with non-exercise fallback", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Two-tier approach addresses jurisdictions where waiver is valid and those where only non-exercise covenant is enforceable. Standard protective language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo irrevocably and unconditionally waives all moral rights under the Copyright, Designs and Patents Act 1988 and any similar rights under the laws of any jurisdiction, including the right to be identified as author and the right to object to derogatory treatment of the Programme.', ARRAY['irrevocably unconditionally waives','CDPA 1988','right to be identified','derogatory treatment']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "UK-specific CDPA waiver", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-specific reference to CDPA 1988 moral rights provisions. Explicit waiver is valid and enforceable under UK law. Standard for UK productions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo hereby waives, and shall procure that all contributors to the Program waive, all moral rights in the Program and Materials. ProdCo shall include appropriate moral rights waiver provisions in all agreements with cast, crew, writers, directors and other contributors.', ARRAY['waives','procure contributors waive','cast crew writers directors','contributor agreements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Waiver with contributor procurement obligation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends moral rights waiver obligation to underlying contributors through ProdCo''s procurement obligation. Essential for complete chain of title clearance."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'To the extent moral rights exist under applicable law and are capable of waiver, ProdCo waives such rights. To the extent such rights exist but cannot be waived (including under French, German, Spanish or other civil law jurisdictions), ProdCo covenants not to exercise such rights and consents to any act or omission that would otherwise infringe such rights.', ARRAY['capable of waiver','waives','cannot be waived','French German Spanish','civil law','covenants not to exercise','consents']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Multi-jurisdiction moral rights provision", "approval": null, "jurisdiction": "EU", "risk_level": "LOW", "reasoning": "Explicitly addresses civil law jurisdictions where moral rights are inalienable. Covenant not to exercise plus consent provides maximum protection available under such laws."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo agrees that Amazon may edit, modify, adapt, translate, dub, subtitle, cut, add to, rearrange, or otherwise alter the Program without limitation and without any obligation to consult with or obtain consent from ProdCo or any other person, and ProdCo waives any right to object to such treatment of the Program.', ARRAY['edit modify adapt','translate dub subtitle','cut add rearrange alter','without limitation','no consent','waives right to object']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Operational waiver framing", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Frames moral rights waiver in operational terms, explicitly permitting specific types of modifications. Useful for addressing integrity right concerns."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo permanently and irrevocably waives any and all moral rights or analogous rights recognized under the laws of any country or jurisdiction, including but not limited to rights of paternity, integrity, divulgation, and withdrawal, and agrees that this waiver shall inure to the benefit of Amazon, its affiliates, licensees, assignees, and successors in perpetuity.', ARRAY['permanently irrevocably waives','any country jurisdiction','paternity integrity divulgation withdrawal','inure to benefit','affiliates licensees assignees successors','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Perpetual worldwide waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive perpetual waiver explicitly extending to all Amazon-related parties worldwide. Enumerates civil law moral rights categories (paternity, divulgation, withdrawal)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo waives all moral rights in the Program to the extent permitted by applicable law. In jurisdictions where such waiver is not recognized, ProdCo agrees not to exercise moral rights, provided that Amazon shall use reasonable efforts to provide credit to the principal creative contributors in accordance with industry custom.', ARRAY['waives moral rights','not exercise','reasonable efforts','credit','principal creative contributors','industry custom']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Non-exercise tied to credit commitment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Ties non-exercise covenant to Amazon credit commitment. ''Reasonable efforts'' and ''industry custom'' qualifiers provide flexibility but require Legal review to ensure no binding credit obligation is created."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo waives moral rights to the maximum extent permitted by law. To the extent moral rights cannot be waived under applicable law, ProdCo shall not assert such rights except in the case of material distortion or mutilation of the Program that is prejudicial to ProdCo''s honor or reputation.', ARRAY['waives maximum extent','cannot be waived','not assert','except material distortion mutilation','prejudicial','honor reputation']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Limited integrity right reservation", "approval": "AMAZON_LEGAL", "jurisdiction": "EU", "risk_level": "MEDIUM", "reasoning": "Reserves integrity right for extreme cases only. This aligns with some civil law formulations of integrity rights. Legal should assess whether ''material distortion or mutilation prejudicial to honor/reputation'' creates operational risk."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo waives all moral rights in the Program. ProdCo shall procure waivers from all contributors; provided that to the extent any contributor refuses to provide such waiver despite ProdCo''s commercially reasonable efforts, ProdCo shall promptly notify Amazon and the parties shall consult in good faith regarding how to proceed.', ARRAY['waives','procure waivers','contributor refuses','commercially reasonable efforts','notify','consult good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Contributor waiver with consultation fallback", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledges practical reality that some contributors may refuse moral rights waiver. Consultation mechanism provides flexibility but Legal should confirm ProdCo remains responsible for contributor clearance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'En la medida permitida por la ley aplicable, el Productor renuncia a todos los derechos morales sobre el Programa. En jurisdicciones donde dicha renuncia no sea válida, el Productor se compromete a no ejercer tales derechos contra Amazon ni sus cesionarios, licenciatarios o sublicenciatarios.', ARRAY['renuncia','derechos morales','no ejercer','cesionarios','licenciatarios','sublicenciatarios']::text[], '{"doc": "PSA_Fallbacks", "section": "Moral Rights", "note": "Spanish-language moral rights provision for LATAM", "approval": "AMAZON_LEGAL", "jurisdiction": "LATAM", "risk_level": "MEDIUM", "reasoning": "Spanish-language formulation for Latin American productions. Non-exercise covenant is appropriate fallback for civil law jurisdictions. Legal should confirm local counsel review for specific country."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo waives and agrees not to assert moral rights in the Program. This waiver and non-assertion agreement is given in consideration of the fees payable hereunder and ProdCo acknowledges such consideration is adequate. ProdCo further agrees to execute any documents reasonably required to evidence this waiver in any jurisdiction.', ARRAY['waives','not assert','consideration','fees','adequate consideration','execute documents','any jurisdiction']::text[], '{"doc": "PSA_Fallbacks", "section": "Moral Rights", "note": "Moral rights waiver with consideration acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "Explicit consideration acknowledgment may strengthen enforceability in certain jurisdictions. Further assurances obligation for moral rights documentation is helpful. Legal should confirm adequacy."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo irrevocably waives moral rights in the Program. To the extent any contributor to the Program has moral rights that have not been waived, Amazon may, in its discretion, either (a) require ProdCo to obtain such waiver as a condition to final payment, or (b) proceed without such waiver at ProdCo''s risk and indemnification.', ARRAY['irrevocably waives','contributor moral rights','not waived','condition to payment','ProdCo risk','indemnification']::text[], '{"doc": "PSA_Fallbacks", "section": "Moral Rights", "note": "Payment condition for contributor waivers", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Provides Amazon flexibility to condition payment on contributor waivers or proceed at ProdCo''s risk. Shifts moral rights clearance risk appropriately. Legal should confirm indemnity coverage is adequate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo retains all moral rights in the Program, including rights of attribution and integrity. Amazon shall not make any changes, alterations, edits or modifications to the Program without ProdCo''s prior written approval.', ARRAY['retains moral rights','attribution','integrity','no changes','prior written approval']::text[], '{"doc": "Counterparty_Proposal", "section": "Moral Rights", "note": "Full moral rights retention with approval requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Full retention of moral rights with approval requirement for modifications fundamentally undermines Amazon''s control over the Program. Incompatible with standard exploitation needs."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo agrees not to assert moral rights against Amazon, except that ProdCo reserves the right to receive credit as producer of the Program in all exploitation, and Amazon shall not release the Program without such credit in a form approved by ProdCo.', ARRAY['not assert','except credit','producer credit','all exploitation','form approved by ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Moral rights reserved for credit control", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Reservation of moral rights for credit control with ProdCo approval creates operational blocking right. Amazon must have sole discretion over credits per standard position."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo waives moral rights only for the purpose of Amazon''s exhibition of the Program on streaming platforms. All moral rights are reserved for any theatrical, broadcast, physical media or other non-streaming exploitation.', ARRAY['waives','streaming only','reserved','theatrical','broadcast','physical media','non-streaming']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Platform-limited moral rights waiver", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Moral rights waiver limited to streaming defeats multi-platform exploitation model. Amazon requires waiver for all media, not just primary streaming platform."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall waive moral rights in the Program upon Amazon''s payment of a separate moral rights buyout fee in the amount of [___] to be negotiated in good faith.', ARRAY['waive','separate fee','moral rights buyout','negotiate good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Separate moral rights fee requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Moral rights waiver is included in Production Fee. Requiring separate payment creates ransom situation and is inconsistent with ownership model."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo agrees not to exercise moral rights for a period of five (5) years from initial release of the Program. Following such period, ProdCo may exercise all moral rights, including requiring restoration of original version and attribution.', ARRAY['not exercise','five years','following period','exercise moral rights','restoration','original version','attribution']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Time-limited moral rights non-exercise", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Time-limited moral rights arrangement creates future liability and operational risk after five years. Amazon requires perpetual waiver/non-exercise consistent with perpetual ownership."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo waives moral rights in the Program, except that Amazon shall not colorize any black-and-white footage, add commercial interruptions, or alter the Program''s aspect ratio without ProdCo''s prior written consent.', ARRAY['waives','except','colorize','commercial interruptions','aspect ratio','prior written consent']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Operational restrictions dressed as moral rights", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Specific operational restrictions requiring consent undermine waiver. While framed as protecting artistic integrity, these create approval requirements for standard exploitation decisions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'In recognition of the importance of moral rights under international law, ProdCo does not waive any moral rights in the Program, and Amazon acknowledges that it shall exploit the Program in a manner consistent with ProdCo''s artistic vision as determined by ProdCo in its reasonable discretion.', ARRAY['does not waive','moral rights','artistic vision','ProdCo reasonable discretion']::text[], '{"doc": "Counterparty_Proposal", "section": "Moral Rights", "note": "No waiver with artistic vision standard", "approval": null, "jurisdiction": "EU", "risk_level": "CRITICAL", "reasoning": "Explicit refusal to waive moral rights combined with ''artistic vision'' standard gives ProdCo ongoing control over exploitation. Fundamentally incompatible with Amazon''s operational needs."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo waives moral rights solely with respect to ProdCo itself. ProdCo makes no representation or warranty regarding moral rights of directors, writers, composers or other contributors, and Amazon shall be solely responsible for obtaining any such waivers.', ARRAY['waives','ProdCo only','no representation warranty','contributors','Amazon responsible']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Waiver limited to ProdCo with contributor carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Shifting contributor moral rights clearance to Amazon is contrary to ProdCo''s production responsibility. ProdCo must procure all necessary waivers from its personnel and contributors."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All fees payable to ProdCo hereunder are subject to and conditioned upon ProdCo not being in uncured, material breach of this Agreement at the time such payment is due.', ARRAY['fees','conditioned upon','not in','uncured material breach','time payment due']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Standard breach condition on fees", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position conditioning payment on absence of uncured material breach. Both ''uncured'' and ''material'' qualifiers are appropriate and industry-standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Payment of any fees or other amounts to ProdCo is expressly conditioned on ProdCo not being in uncured, material breach of any of its obligations under this Agreement or any related agreement between the parties.', ARRAY['payment conditioned','uncured material breach','obligations','related agreement']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Extended to related agreements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends breach condition to related agreements (e.g., development agreements, option agreements), which is appropriate for integrated deal structures."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s right to receive fees is subject to and contingent upon ProdCo not being in uncured, material breach of this Agreement. For the avoidance of doubt, Amazon''s obligation to pay shall be suspended during any period in which ProdCo is in such breach.', ARRAY['right to receive','contingent','uncured material breach','obligation suspended','during breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Explicit suspension language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly states suspension of payment obligation during breach period, providing additional clarity on Amazon''s rights. Standard acceptable position."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Each installment of the Production Fee is conditioned upon ProdCo not being in uncured, material breach of this Agreement as of the date such installment is due. Amazon may withhold any payment pending cure of any such breach.', ARRAY['each installment','Production Fee','conditioned','uncured material breach','withhold','pending cure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Installment-specific conditioning", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Applies breach condition to each installment, with explicit withholding right. Standard for milestone-based payment structures."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All compensation payable by Amazon to ProdCo pursuant to this Agreement or Exhibit A attached hereto shall be subject to and conditioned upon ProdCo''s compliance with its obligations hereunder and ProdCo not being in uncured, material breach hereof.', ARRAY['all compensation','Exhibit A','conditioned','compliance','obligations','uncured material breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Covers Exhibit A compensation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly references Exhibit A (typically the detailed fee schedule) ensuring all compensation categories are covered by the breach condition."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The fees set forth in Exhibit A are payable subject to ProdCo not being in uncured, material breach of this Agreement. In the event of such breach, Amazon may, in its sole discretion, either withhold payment until the breach is cured or terminate this Agreement in accordance with the termination provisions hereof.', ARRAY['fees','Exhibit A','uncured material breach','sole discretion','withhold','terminate']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Alternative remedies for breach", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Provides Amazon with election between withholding and termination in event of breach. Preserves flexibility while maintaining standard breach condition."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Payment of fees hereunder is conditioned upon ProdCo not being in uncured, material breach of this Agreement. Notice of any such breach shall be provided in writing, and ProdCo shall have ten (10) business days following receipt of such notice to cure any curable breach before Amazon may exercise its withholding rights.', ARRAY['conditioned','uncured material breach','notice in writing','ten business days','cure','curable breach','withholding rights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Includes notice and cure period", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Incorporates procedural protections (notice, cure period) while maintaining breach condition. Ten business days is reasonable and industry-standard."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Payment of fees is conditioned upon ProdCo not being in uncured, material breach of this Agreement, provided that ''material breach'' shall mean a breach that has a material adverse effect on the production, delivery or exploitation of the Program.', ARRAY['conditioned','uncured material breach','material breach defined','material adverse effect','production delivery exploitation']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Definition of material breach", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "ProdCo attempt to define ''material breach'' narrowly. Definition focuses on Program impact which is reasonable, but Legal should confirm it doesn''t exclude other significant breaches (e.g., confidentiality, IP assignments)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All fees are conditioned upon ProdCo not being in uncured, material breach. Prior to withholding any payment, Amazon shall provide written notice to ProdCo specifying the alleged breach in reasonable detail, and ProdCo shall have fifteen (15) business days to cure such breach or to dispute the existence of such breach in writing.', ARRAY['conditioned','uncured material breach','written notice','reasonable detail','fifteen business days','cure or dispute']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Extended cure period with dispute mechanism", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Fifteen-day cure period is longer than standard ten days. Dispute mechanism could create delay but may be acceptable if it doesn''t prevent withholding. Legal should review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Payment of fees is subject to ProdCo not being in uncured, material breach. Notwithstanding the foregoing, Amazon shall not withhold any payment on account of an alleged breach that is the subject of a good faith dispute between the parties.', ARRAY['subject to','uncured material breach','not withhold','alleged breach','good faith dispute']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Good faith dispute carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Good faith dispute carveout could limit Amazon''s withholding right during disputes. Legal should assess whether this unduly restricts Amazon''s leverage during breach situations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Fees are conditioned upon ProdCo not being in uncured, material breach. In the event Amazon withholds any payment pursuant to this provision, Amazon shall pay interest on any withheld amounts at the rate of [Prime + 2%] per annum from the original due date if it is subsequently determined that no breach occurred.', ARRAY['conditioned','uncured material breach','withholds','interest','Prime plus 2%','no breach occurred']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Interest on wrongfully withheld amounts", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Interest on wrongfully withheld amounts provides ProdCo protection against improper withholding. May be acceptable at reasonable rate. Legal and Finance should approve rate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Payment of the Production Fee is conditioned upon ProdCo not being in uncured, material breach, provided that amounts due for actual third-party production costs already incurred shall not be subject to withholding and shall be paid as scheduled.', ARRAY['Production Fee','conditioned','uncured material breach','third-party production costs','not subject to withholding']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Carveout for third-party costs", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for third-party costs already incurred is reasonable to avoid disrupting production vendors. Business Affairs should confirm scope is appropriately limited to documented third-party costs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All fees are subject to ProdCo not being in uncured, material breach. For purposes of this provision, a breach shall not be considered ''material'' if ProdCo is using commercially reasonable efforts to remedy such breach and such breach does not materially impair Amazon''s rights or the Program.', ARRAY['uncured material breach','commercially reasonable efforts','remedy','materially impair','Amazon''s rights','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Efforts-based materiality carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Efforts-based carveout could reduce Amazon''s leverage if ProdCo claims to be working on cure. Legal should assess whether this is acceptable given other protections."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'All fees payable to ProdCo hereunder are unconditional and shall be paid when due regardless of any breach or alleged breach by ProdCo. Amazon''s sole remedy for any breach shall be a claim for damages.', ARRAY['unconditional','paid when due','regardless of breach','sole remedy','damages']::text[], '{"doc": "Counterparty_Proposal", "section": "Fees/Payment", "note": "Unconditional payment obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Removing breach condition entirely eliminates Amazon''s primary leverage to ensure ProdCo performance. Unconditional payment obligation is fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Payment of fees is conditioned upon ProdCo not being in material breach, as determined by final, non-appealable judgment of a court of competent jurisdiction.', ARRAY['conditioned','material breach','final non-appealable judgment','court']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Judicial determination required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring judicial determination before withholding renders the breach condition meaningless. Litigation could take years, eliminating Amazon''s operational leverage."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Fees are conditioned upon ProdCo not being in uncured, material breach of this Agreement. For purposes of this provision, ''material breach'' shall mean only a breach resulting in ProdCo''s failure to deliver the completed Program.', ARRAY['conditioned','uncured material breach','material breach means','only','failure to deliver']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Extremely narrow materiality definition", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Defining material breach as only delivery failure excludes all other significant breaches (IP, confidentiality, compliance, reps/warranties). This gutting of the breach condition is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Fees are payable subject to ProdCo not being in uncured, material breach. Notwithstanding the foregoing, if Amazon withholds any payment and ProdCo disputes such withholding, ProdCo may suspend all services and Amazon shall continue to pay all crew and vendor costs during such suspension.', ARRAY['uncured material breach','withholds','ProdCo disputes','suspend services','Amazon pays costs']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "ProdCo suspension right with cost allocation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Allowing ProdCo to suspend services while Amazon pays costs in response to disputed withholding inverts the leverage structure entirely. This is fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Payment is conditioned upon ProdCo not being in uncured, material, willful, persistent breach of this Agreement that has been the subject of at least three (3) prior written notices from Amazon.', ARRAY['uncured','material','willful','persistent','three prior notices']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Stacked qualifiers on breach", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Adding ''willful,'' ''persistent,'' and three-notice requirement to already-qualified ''uncured, material'' makes it nearly impossible to invoke the breach condition. This accumulation of qualifiers is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Payment of fees is conditioned upon ProdCo not being in material breach. ProdCo shall have one hundred eighty (180) days following written notice to cure any breach, and Amazon may not withhold payment during such cure period.', ARRAY['conditioned','material breach','180 days','cure','no withholding during cure']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Excessive cure period with no withholding", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "180-day cure period is grossly excessive (standard is 10-15 business days), and prohibition on withholding during cure eliminates Amazon''s leverage entirely."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'All fees shall be paid as and when due. Amazon acknowledges that ProdCo''s cash flow depends on timely payment and agrees that any withholding of fees, regardless of reason, shall constitute a material breach by Amazon entitling ProdCo to terminate this Agreement.', ARRAY['paid when due','cash flow','withholding','material breach by Amazon','ProdCo terminate']::text[], '{"doc": "Counterparty_Proposal", "section": "Fees/Payment", "note": "Withholding as Amazon breach", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Characterizing any withholding as Amazon breach with ProdCo termination right completely inverts the commercial relationship. Amazon must retain withholding right for ProdCo breach."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All fees payable to ProdCo pursuant to this Agreement are subject to and conditioned upon all other terms and conditions of this Agreement, including without limitation the representations, warranties and indemnities set forth herein.', ARRAY['fees','subject to','conditioned upon','all other terms','representations','warranties','indemnities']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Standard terms and conditions conditioning", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard language ensuring fee payment is integrated with all Agreement obligations. Prevents argument that fees are independent of other terms."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Payment of the Production Fee and all other amounts hereunder is expressly subject to and conditioned upon ProdCo''s full compliance with all terms, conditions, representations, warranties, covenants and obligations set forth in this Agreement and any exhibits or schedules hereto.', ARRAY['Production Fee','all amounts','expressly subject to','full compliance','terms conditions','exhibits schedules']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Comprehensive conditioning including exhibits", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly includes exhibits and schedules, ensuring fee conditions apply to all components of the integrated agreement. Standard Amazon position."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The fees set forth in Exhibit A are subject to all terms and conditions of this Agreement. Without limiting the foregoing, payment is conditioned upon timely delivery of all Materials, execution of all required documentation, and ProdCo not being in breach of any provision hereof.', ARRAY['fees','Exhibit A','subject to all terms','timely delivery','execution of documentation','not in breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Specific operational conditions enumerated", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates key operational conditions (delivery, documentation) in addition to general terms conditioning. Provides additional clarity on payment prerequisites."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Fees hereunder are subject to all other terms and conditions of this Agreement. Amazon''s obligation to pay any installment is further conditioned upon Amazon''s approval of the applicable deliverable and receipt of all chain of title documentation required hereunder.', ARRAY['subject to all terms','Amazon approval','deliverable','chain of title documentation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Approval and documentation conditions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Ties payment to deliverable approval and chain of title documentation, which are standard production payment conditions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All compensation payable to ProdCo is subject to and conditioned upon all other terms of this Agreement. ProdCo acknowledges that the fees set forth herein are the total compensation for all rights granted and services rendered, and no additional compensation shall be due except as expressly provided.', ARRAY['compensation','subject to','conditioned','total compensation','all rights','services','no additional compensation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Total compensation acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes important acknowledgment that stated fees are total compensation, preventing later claims for additional payment. Standard protective language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Payment of fees is subject to all other terms and conditions hereof, including without limitation ProdCo''s compliance with all applicable laws, Amazon policies and guidelines, and the production schedule set forth in Exhibit B.', ARRAY['subject to','compliance','applicable laws','Amazon policies','guidelines','production schedule','Exhibit B']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Includes policy and schedule compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly references compliance with laws, Amazon policies, and production schedule as payment conditions. Comprehensive and acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The fees payable pursuant to Exhibit A are subject to and contingent upon all terms, conditions and covenants of this Agreement. In the event of any conflict between Exhibit A and this Agreement, the terms of this Agreement shall control.', ARRAY['fees','Exhibit A','subject to','contingent','terms conditions covenants','conflict','Agreement controls']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Hierarchy provision for exhibit conflicts", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Establishes hierarchy with main Agreement controlling over Exhibit A in case of conflicts. Prevents Exhibit A carveouts from overriding principal terms."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Fees are subject to all other terms and conditions of this Agreement, provided that Amazon shall not condition payment on compliance with any term or condition that was not disclosed to ProdCo in writing prior to commencement of production.', ARRAY['subject to','all terms','not condition','not disclosed','writing','prior to commencement']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Disclosure limitation on conditioning", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limitation to disclosed terms is reasonable as it prevents post-hoc creation of payment conditions. Legal should confirm all relevant terms are in fact disclosed in the Agreement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Payment is subject to all terms of this Agreement. If Amazon believes ProdCo has failed to satisfy any condition to payment, Amazon shall notify ProdCo in writing with reasonable specificity, and ProdCo shall have ten (10) business days to cure or provide evidence of compliance.', ARRAY['subject to all terms','notify','reasonable specificity','ten business days','cure','evidence of compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Notice and cure mechanism for conditions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notice and cure mechanism is reasonable and provides procedural fairness without eliminating conditions. Ten-day period is acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Fees are subject to all other terms and conditions hereof. Notwithstanding the foregoing, Amazon shall not withhold or delay payment based on immaterial or technical non-compliance with Agreement terms that does not affect the Program or Amazon''s rights therein.', ARRAY['subject to all terms','not withhold','immaterial','technical non-compliance','does not affect','Program','Amazon''s rights']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Immaterial non-compliance carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for truly immaterial non-compliance may be reasonable but could be subject to dispute. Legal should assess whether this creates interpretive issues."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Payment is subject to all terms and conditions of this Agreement. If Amazon determines that any condition to payment has not been satisfied, Amazon shall provide prompt written notice to ProdCo, and the parties shall meet within five (5) business days to resolve the matter in good faith.', ARRAY['subject to all terms','condition not satisfied','prompt notice','meet','five business days','resolve','good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Meet and confer requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Meet and confer requirement adds procedural step but doesn''t eliminate conditions. Legal should confirm this doesn''t unduly delay Amazon''s ability to withhold."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All fees are subject to the terms and conditions of this Agreement. ProdCo acknowledges that certain fees are conditioned upon specific deliverable approvals as set forth in Exhibit A, and that the parties shall work together in good faith to resolve any approval issues promptly.', ARRAY['subject to terms','deliverable approvals','Exhibit A','work together','good faith','resolve','promptly']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Good faith resolution for approval issues", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Good faith resolution language for approval issues is acceptable if it doesn''t limit Amazon''s ultimate approval discretion. Legal should review Exhibit A approval provisions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Fees are subject to all terms of this Agreement, except that fees for services already performed by ProdCo as of the date of any alleged non-compliance shall not be subject to forfeiture or clawback.', ARRAY['subject to all terms','except','services performed','alleged non-compliance','no forfeiture','no clawback']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Anti-clawback for earned fees", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Anti-clawback for services already performed may be reasonable from equity standpoint but limits Amazon''s remedies. Legal should assess interaction with indemnity and set-off rights."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The fees set forth in Exhibit A are payable unconditionally and are not subject to any terms, conditions, or other provisions of this Agreement. Payment obligations shall be independent of all other covenants herein.', ARRAY['unconditionally','not subject to','any terms','independent','all other covenants']::text[], '{"doc": "Counterparty_Proposal", "section": "Fees/Payment", "note": "Unconditional independent payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Making payment unconditional and independent of Agreement terms eliminates Amazon''s ability to enforce compliance through payment leverage. Fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Fees are subject to the payment schedule in Exhibit A only and shall not be conditioned upon, reduced by, or offset against any other terms, conditions, claims or obligations arising under this Agreement.', ARRAY['Exhibit A only','not conditioned','reduced','offset','claims','obligations']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "No set-off or offset rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating set-off rights removes a critical Amazon remedy. Payment must be subject to set-off for claims, damages, and other amounts owed by ProdCo."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Payment of fees is subject to all terms of this Agreement. Notwithstanding the foregoing, if ProdCo disputes any Amazon determination that a condition has not been satisfied, ProdCo may submit the dispute to expedited arbitration, and Amazon shall pay the disputed amount into escrow pending resolution.', ARRAY['subject to all terms','disputes','expedited arbitration','pay into escrow','pending resolution']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Escrow requirement for disputes", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring Amazon to pay disputed amounts into escrow eliminates withholding leverage and forces payment despite ProdCo non-compliance. This is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'While fees are generally subject to the terms of this Agreement, ProdCo shall be entitled to full payment of all fees if ProdCo has substantially performed its obligations, even if technical breaches or minor non-compliance exist.', ARRAY['generally subject','full payment','substantially performed','technical breaches','minor non-compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Substantial performance standard", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Substantial performance'' standard borrowed from construction law is inappropriate for media production agreements. Creates ambiguity about what constitutes sufficient compliance."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Fees are subject to all terms and conditions hereof. If Amazon withholds any fee based on alleged non-satisfaction of any condition, ProdCo may elect to suspend all production activities until payment is made, and any resulting delays shall extend the delivery schedule day-for-day.', ARRAY['subject to all terms','withholds','ProdCo suspend production','delays extend schedule']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "ProdCo suspension right", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Giving ProdCo suspension rights in response to withholding (even for legitimate non-compliance) inverts the contractual leverage structure and is commercially unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Payment of fees shall be subject only to those specific conditions expressly enumerated in Exhibit A. No other term, condition, representation, warranty, covenant or obligation in this Agreement shall constitute a condition to payment.', ARRAY['subject only to','Exhibit A','no other term','representation warranty','not condition to payment']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Limited conditioning to Exhibit A only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting payment conditions to Exhibit A only excludes critical Agreement provisions (reps/warranties, indemnities, IP assignment) from payment leverage. Fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Fees are subject to all terms of this Agreement, provided that Amazon must exercise any withholding right within thirty (30) days of becoming aware of the applicable non-compliance. Failure to withhold within such period shall constitute waiver of such right.', ARRAY['subject to all terms','withhold within 30 days','aware of non-compliance','waiver']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Time-limited withholding with waiver", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "30-day waiver provision is unreasonably short and could result in loss of withholding rights before full scope of non-compliance is discovered. Amazon needs ongoing right to condition payment."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All entitlements set forth in this Agreement or Exhibit A are subject to and conditioned upon (i) completion of ProdCo''s services hereunder, and (ii) ProdCo not being in uncured, material breach of this Agreement.', ARRAY['entitlements','conditioned','completion of services','not in','uncured material breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Standard entitlements condition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard conditioning of entitlements on completion and no breach. Entitlements (perks, residuals, bonuses) require these baseline conditions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s entitlement to credit, bonus compensation, profit participation or any other benefits described herein is expressly conditioned upon ProdCo''s full performance and completion of all services and ProdCo not being in uncured, material breach of this Agreement at any time during or after production.', ARRAY['entitlement','credit','bonus','profit participation','benefits','full performance','completion','uncured material breach','during or after production']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Comprehensive entitlements enumeration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly enumerates credit, bonus, and profit participation as conditioned entitlements. ''During or after production'' extends condition appropriately."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Entitlements are conditioned upon completion of services and ProdCo not being in uncured, material breach. For purposes of this provision, ''completion'' means ProdCo has rendered all services required hereunder through final delivery and acceptance of the Program by Amazon.', ARRAY['entitlements conditioned','completion','uncured material breach','completion means','final delivery','acceptance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Defined completion standard", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Defines ''completion'' as including final delivery and acceptance, ensuring entitlements don''t vest until Amazon has accepted all deliverables."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All entitlements, including without limitation any residual or reuse payments, sequel/spinoff fees, or passive payments, shall be subject to and conditioned upon completion of ProdCo''s obligations and ProdCo not being in uncured, material breach of this Agreement.', ARRAY['entitlements','residual','reuse payments','sequel spinoff fees','passive payments','conditioned','completion','uncured material breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Extended to all contingent payments", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly covers residuals, sequel fees, and passive payments under entitlement conditions. Comprehensive coverage of contingent compensation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Entitlements are conditioned upon (a) ProdCo completing all services, (b) delivery of all required Materials to Amazon''s satisfaction, and (c) ProdCo not being in uncured, material breach of this Agreement or any other agreement between ProdCo and Amazon or its affiliates.', ARRAY['entitlements conditioned','completing services','delivery','Amazon''s satisfaction','uncured material breach','any other agreement','affiliates']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Cross-default with affiliates", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes cross-default to other Amazon/affiliate agreements, preventing ProdCo from maintaining entitlements despite breach of related deals."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s entitlements under this Agreement shall vest only upon completion of services and absence of uncured, material breach. Prior to vesting, Amazon may suspend or terminate any entitlement if ProdCo is in breach or has failed to perform.', ARRAY['entitlements','vest','completion','absence of breach','prior to vesting','suspend','terminate','failed to perform']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Vesting concept with suspension right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Uses vesting concept common in employment context, with clear Amazon rights to suspend or terminate pre-vesting. Standard acceptable approach."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All entitlements are subject to completion and no uncured, material breach. If ProdCo is removed or replaced prior to completion for any reason other than Amazon''s convenience, ProdCo shall forfeit all entitlements, and Amazon shall have no obligation to pay any amounts other than fees earned through the date of removal.', ARRAY['entitlements','completion','uncured material breach','removed replaced','forfeit','no obligation','fees earned','date of removal']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Forfeiture upon removal", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear forfeiture consequence for removal, with carveout only for Amazon convenience removal. Provides appropriate Amazon protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Entitlements are conditioned upon completion and no uncured, material breach. If ProdCo is terminated by Amazon for cause, entitlements shall be forfeited; however, if ProdCo is terminated for Amazon''s convenience, ProdCo shall receive a pro-rata portion of entitlements based on services performed.', ARRAY['entitlements conditioned','completion','uncured material breach','terminated for cause','forfeited','convenience','pro-rata','services performed']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Pro-rata entitlements on convenience termination", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Pro-rata entitlement for convenience termination is a common ProdCo ask. May be acceptable for major producers. Legal should assess specific entitlements subject to pro-rata treatment."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Entitlements are subject to completion and no uncured, material breach. Notwithstanding the foregoing, if ProdCo completes principal photography but is removed prior to post-production, ProdCo shall retain credit entitlements (but not financial entitlements) earned through principal photography.', ARRAY['entitlements','completion','uncured material breach','principal photography','removed','retain credit entitlements','not financial entitlements']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Credit retention post-principal photography", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Retaining credit (but not financial) entitlements after principal photography may be reasonable where ProdCo has made substantial contribution. Legal should assess specific credits affected."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All entitlements are conditioned upon completion and no uncured, material breach; provided that ProdCo shall receive written notice of any alleged breach and shall have twenty (20) business days to cure such breach before forfeiture of any entitlement.', ARRAY['entitlements conditioned','completion','uncured material breach','written notice','twenty business days','cure','forfeiture']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Extended cure period for entitlement forfeiture", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Twenty-day cure period is longer than standard but may be acceptable given severity of entitlement forfeiture. Legal should confirm adequacy."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Entitlements are conditioned upon completion and no uncured, material breach. In the event of a disputed breach, entitlements shall be held in abeyance pending resolution; if the dispute is resolved in ProdCo''s favor, entitlements shall be reinstated retroactively.', ARRAY['entitlements conditioned','completion','uncured material breach','disputed breach','abeyance','resolution','reinstated retroactively']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Abeyance for disputed breaches", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Abeyance mechanism for disputed breaches preserves entitlements pending resolution. Retroactive reinstatement is reasonable if no breach occurred. Legal should review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Entitlements are subject to completion of services and absence of uncured, material breach. For the avoidance of doubt, ''completion'' shall include substantial completion, meaning performance of at least ninety percent (90%) of required services, with remaining services being immaterial to the Program.', ARRAY['entitlements','completion','uncured material breach','substantial completion','ninety percent','remaining services','immaterial']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Substantial completion standard", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Substantial completion (90%) standard may be acceptable depending on what services could be excluded. Legal should confirm this doesn''t allow key deliverables to be incomplete."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s entitlements are conditioned upon completion and no uncured, material breach. If ProdCo is unable to complete services due to disability, death, or force majeure affecting ProdCo''s key personnel, entitlements shall be prorated based on services actually rendered.', ARRAY['entitlements conditioned','completion','uncured material breach','disability','death','force majeure','key personnel','prorated','services rendered']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Proration for force majeure/disability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Proration for disability, death, or force majeure affecting key personnel is reasonable equity-based protection. Legal should confirm scope of ''key personnel.''"}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s entitlements shall vest immediately upon execution of this Agreement and shall not be subject to any conditions, including completion of services or absence of breach.', ARRAY['entitlements vest','immediately','execution','not subject','conditions','completion','breach']::text[], '{"doc": "Counterparty_Proposal", "section": "Entitlements", "note": "Unconditional immediate vesting", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Immediate unconditional vesting eliminates Amazon''s ability to condition entitlements on performance. This is fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Entitlements are conditioned upon completion, but shall not be conditioned upon absence of breach. ProdCo''s entitlements shall be payable regardless of any breach of this Agreement, subject only to Amazon''s right to pursue damages separately.', ARRAY['entitlements conditioned','completion','not conditioned','absence of breach','payable regardless','damages separately']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Breach condition removed", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Removing breach condition from entitlements eliminates Amazon''s leverage for compliance. Entitlements must remain subject to no-breach condition."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Entitlements are conditioned upon completion and no material breach. If Amazon alleges a breach, ProdCo may contest such allegation in binding arbitration, and entitlements shall continue to be paid pending final arbitration award.', ARRAY['entitlements conditioned','completion','material breach','contest','binding arbitration','continue to be paid','pending award']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Payment during arbitration", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring continued entitlement payment pending arbitration eliminates Amazon''s leverage and creates potential for unrecoverable payments. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Entitlements shall vest upon completion of principal photography and shall not be affected by any subsequent breach or failure to complete post-production services.', ARRAY['entitlements vest','principal photography','not affected','subsequent breach','failure','post-production']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Early vesting at principal photography", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Vesting entitlements at principal photography with no subsequent breach condition leaves Amazon without leverage for post-production compliance. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Entitlements are conditioned upon completion and no uncured, material breach, provided that any breach must be (i) adjudicated by a court of competent jurisdiction, (ii) have caused damages exceeding $1,000,000, and (iii) not be subject to insurance coverage.', ARRAY['entitlements conditioned','completion','uncured material breach','adjudicated','court','damages exceeding','one million','insurance coverage']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Stacked requirements for breach finding", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring adjudication, $1M+ damages, and no insurance coverage makes breach condition nearly impossible to invoke. These stacked requirements are unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s credit entitlements shall be unconditional. All other entitlements are conditioned upon completion and no uncured, material breach. Amazon shall not withhold or condition credit on any basis.', ARRAY['credit entitlements','unconditional','other entitlements','conditioned','completion','not withhold','credit','any basis']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Credit entitlements carved out", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Making credit unconditional conflicts with Amazon''s sole discretion over credits. Credit must remain within Amazon''s control like other entitlements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Entitlements are subject to completion only. The concept of ''uncured, material breach'' is deleted. ProdCo shall be entitled to all entitlements upon rendering substantially all services regardless of any alleged breach or non-compliance.', ARRAY['entitlements','completion only','uncured material breach','deleted','entitled','substantially all services','regardless','alleged breach']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Breach condition deleted entirely", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Complete deletion of breach condition is unacceptable. Amazon must maintain ability to withhold entitlements for material breach."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Any credit to be accorded to ProdCo or any other person in connection with the Program shall be determined by Amazon in its sole discretion.', ARRAY['credit','ProdCo','any other person','determined','Amazon','sole discretion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Standard sole discretion language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position reserving absolute discretion over all credits. This is essential for maintaining creative and business control over the Program."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All matters relating to credit, including form, size, placement, duration and order of credits, shall be within Amazon''s sole and absolute discretion.', ARRAY['credit','form','size','placement','duration','order','sole and absolute discretion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Comprehensive credit elements enumerated", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific credit elements (form, size, placement, duration, order) all within sole discretion. Comprehensive and clear."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Credit, if any, shall be accorded in Amazon''s sole discretion, including whether to accord credit at all, the form and manner of any credit, and the media in which credit may appear.', ARRAY['credit if any','sole discretion','whether to accord','form manner','media']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Explicit ''if any'' language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''If any'' makes clear that credit itself is discretionary, not just its form. Important for maximum flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have sole discretion with respect to all credit decisions, including without limitation credits for producers, executive producers, directors, writers, cast, crew and all other contributors to the Program.', ARRAY['sole discretion','credit decisions','producers','executive producers','directors','writers','cast','crew','contributors']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Applies to all contributor categories", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly extends sole discretion to all contributor categories, preventing arguments that discretion applies only to ProdCo credit."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Credit shall be determined by Amazon in its sole discretion, consistent with Amazon''s then-current credit policies and any applicable guild requirements. Subject to the foregoing, Amazon shall have no obligation to accord credit to any person.', ARRAY['sole discretion','Amazon credit policies','guild requirements','no obligation','any person']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Acknowledges guild requirements only", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Appropriately acknowledges that guild requirements may impose minimum credit obligations while preserving sole discretion for all other matters."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s decisions regarding credit shall be final, binding and non-appealable, and shall be made in Amazon''s sole discretion. ProdCo hereby waives any right to challenge, dispute or seek review of any credit determination.', ARRAY['decisions','credit','final binding non-appealable','sole discretion','waives','challenge dispute review']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Finality and waiver language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Adds finality and waiver language to prevent credit disputes. Strong protection of Amazon''s discretion."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All credit determinations are within Amazon''s sole discretion and shall be subject to change at any time without notice to or consent from ProdCo or any other party.', ARRAY['credit determinations','sole discretion','subject to change','any time','without notice','without consent']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Right to change without notice", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Preserves Amazon''s right to modify credits at any time without process, which is important for responding to changed circumstances or creative decisions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit shall be determined by Amazon in its sole discretion; provided that Amazon shall accord ProdCo an ''Executive Producer'' credit in the main titles of the Program if ProdCo completes all services and is not in uncured material breach.', ARRAY['sole discretion','provided that','Executive Producer','main titles','completes services','not in breach']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Specific credit commitment for ProdCo", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Specific EP credit commitment for ProdCo may be acceptable for major producers if conditioned on completion and no breach. Legal should confirm this is negotiated outcome."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit shall be within Amazon''s sole discretion, except that Amazon agrees to use good faith efforts to provide ProdCo an on-screen producer credit consistent with industry custom for comparable productions.', ARRAY['sole discretion','except','good faith efforts','producer credit','industry custom','comparable productions']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Good faith efforts for producer credit", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "''Good faith efforts'' standard for producer credit is softer than absolute commitment. May be acceptable if ''industry custom'' provides flexibility. Legal should review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit is within Amazon''s sole discretion. Notwithstanding the foregoing, if Amazon accords any producer credit to any third party, Amazon shall also accord a comparable producer credit to ProdCo.', ARRAY['sole discretion','notwithstanding','producer credit','third party','comparable','ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Most favored nations for producer credit", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "MFN for producer credit relative to other producers. May be acceptable depending on other producer arrangements. Legal should assess impact on credit flexibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have sole discretion over all credit matters, provided that Amazon shall consult with ProdCo regarding producer credits prior to finalizing the credit block, though Amazon shall retain final decision-making authority.', ARRAY['sole discretion','consult','producer credits','prior to finalizing','credit block','final decision-making authority']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Consultation right without approval", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Consultation (without approval right) before finalizing credits is minimally intrusive. Legal should confirm ''final decision-making authority'' language is clear."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit shall be in Amazon''s sole discretion. In exercising such discretion, Amazon shall consider in good faith any reasonable credit requests submitted by ProdCo in writing, but Amazon shall have no obligation to honor any such request.', ARRAY['sole discretion','consider in good faith','reasonable credit requests','in writing','no obligation','honor request']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Good faith consideration without obligation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Agreeing to ''consider'' requests without obligation to honor them is relatively low risk. May be acceptable as relationship gesture."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit is in Amazon''s sole discretion. If Amazon removes or reduces ProdCo''s credit after initial determination, Amazon shall provide ProdCo written notice and a brief explanation of the reason for such change.', ARRAY['sole discretion','removes reduces','initial determination','written notice','brief explanation','reason']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Notice for credit reduction", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notice and brief explanation for credit changes doesn''t limit Amazon''s discretion but provides courtesy to ProdCo. May be acceptable for relationship purposes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall receive an ''Executive Producer'' credit in the main titles of the Program, in first position among all producer credits, in a size and style no less prominent than any other credit.', ARRAY['Executive Producer','main titles','first position','no less prominent','any other credit']::text[], '{"doc": "Counterparty_Proposal", "section": "Credit", "note": "Guaranteed position and prominence", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Guaranteed credit position and prominence eliminates Amazon''s discretion and creates potential conflicts with other credit commitments. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon and ProdCo shall mutually agree upon all credits to be accorded in connection with the Program. Neither party shall finalize credits without the written approval of the other.', ARRAY['mutually agree','all credits','neither party','finalize','written approval','other']::text[], '{"doc": "Counterparty_Proposal", "section": "Credit", "note": "Mutual approval requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mutual approval requirement gives ProdCo blocking power over all credits. This fundamentally undermines Amazon''s creative and business control."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Credit shall be in Amazon''s reasonable discretion, and Amazon shall not unreasonably withhold, condition or delay any credit reasonably requested by ProdCo.', ARRAY['reasonable discretion','not unreasonably withhold','condition','delay','reasonably requested']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Reasonable discretion standard", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Reasonable discretion'' with ''not unreasonably withhold'' standard exposes Amazon to disputes about what is reasonable. Amazon requires sole discretion."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall have the right to approve all credits relating to ProdCo and its personnel. Amazon shall submit proposed credits to ProdCo for approval at least thirty (30) days prior to the scheduled initial release date.', ARRAY['right to approve','credits','ProdCo personnel','submit','thirty days','prior to release']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "ProdCo approval over its credits", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo approval right over credits is contrary to Amazon''s sole discretion requirement. Creates potential delays and disputes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall accord credit in accordance with the credit schedule attached hereto as Exhibit D. Amazon may not deviate from Exhibit D without ProdCo''s prior written consent.', ARRAY['credit schedule','Exhibit D','may not deviate','prior written consent']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Fixed credit schedule with no deviation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Fixed credit schedule with no deviation right locks Amazon into commitments that may become problematic. Amazon must retain flexibility."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Credit decisions shall be made by a committee consisting of one representative from Amazon and one representative from ProdCo. In the event of disagreement, the matter shall be submitted to binding arbitration.', ARRAY['committee','representative','Amazon','ProdCo','disagreement','binding arbitration']::text[], '{"doc": "Counterparty_Proposal", "section": "Credit", "note": "Joint credit committee", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Joint credit committee with arbitration creates unacceptable operational complexity and eliminates Amazon''s unilateral control. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Credit is within Amazon''s discretion. However, if Amazon fails to accord ProdCo a producer credit in the main titles, ProdCo shall be entitled to additional compensation equal to 10% of the Production Fee as liquidated damages.', ARRAY['discretion','fails to accord','producer credit','main titles','additional compensation','10%','liquidated damages']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Liquidated damages for no credit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Liquidated damages for credit decisions effectively monetizes what should be discretionary. Creates pressure to accord credit regardless of merit."}'::jsonb)
